insert into public.places (id, name, area, lat, lng, tags, duration_min, cost_band, indoor, mrt, hours, closed_days, min_window_h, blurb, captions, safety_notes, image_url, image_credit) values
  ('jewel-rain-vortex', 'Jewel Rain Vortex', 'Changi', 1.3602, 103.9894, array['photo', 'gardens', 'views', 'architecture']::text[], 40, 0, true, 'Changi Airport', '[["10:00","22:00"]]'::jsonb, '{}'::int[], null, 'The world''s tallest indoor waterfall pours 40 metres through a glass doughnut roof inside Jewel, a short walk from every terminal.', array['The waterfall is louder than you expect, stand at the B2 rail for the spray shot.', 'Evening light-and-sound show turns the vortex into a projection screen.', 'Walkable from T1 in 5 minutes, T2/T3 via linkbridge in 10.']::text[], 'Landside: you must clear immigration to reach it.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Jewel_Changi_Airport_13-11-2023%281%29.jpg/960px-Jewel_Changi_Airport_13-11-2023%281%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Jewel Changi Airport'),
  ('jewel-canopy-park', 'Canopy Park, Jewel', 'Changi', 1.3606, 103.9897, array['gardens', 'photo', 'nature']::text[], 60, 2, true, 'Changi Airport', '[["10:00","22:00"]]'::jsonb, '{}'::int[], null, 'Topiary walks, a hedge maze, mist bowls and a glass-floored bridge on Jewel''s top level, looking down on the Rain Vortex.', '{}'::text[], 'Ticketed; buy at the L5 counter or online.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Jewel_Changi_Airport_13-11-2023%281%29.jpg/960px-Jewel_Changi_Airport_13-11-2023%281%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Jewel Changi Airport'),
  ('jewel-forest-valley', 'Shiseido Forest Valley', 'Changi', 1.3598, 103.9898, array['gardens', 'nature', 'photo']::text[], 30, 0, true, 'Changi Airport', '"24h"'::jsonb, '{}'::int[], null, 'A terraced indoor forest of 2,000 trees and shrubs wrapping around the vortex, free, open all night, perfect for a jet-lag stroll.', '{}'::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Jewel_Changi_Airport_13-11-2023%281%29.jpg/960px-Jewel_Changi_Airport_13-11-2023%281%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Jewel Changi Airport'),
  ('changi-chapel-museum', 'Changi Chapel & Museum', 'Changi', 1.359, 103.9738, array['museum', 'heritage', 'culture']::text[], 60, 0, true, 'Changi Airport', '[["09:30","17:30"]]'::jsonb, array[1]::int[], null, 'Quiet, moving museum on the WWII prisoners of war held at Changi, with a replica of the chapel they built.', '{}'::text[], 'Closed Mondays. Taxi recommended from the airport.', 'https://upload.wikimedia.org/wikipedia/commons/6/69/Changi_Museum.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled', 'Wikipedia: Changi Chapel and Museum'),
  ('changi-village-hawker', 'Changi Village Hawker Centre', 'Changi', 1.3893, 103.9876, array['hawker', 'food']::text[], 45, 1, true, 'Changi Airport', '[["07:00","23:00"]]'::jsonb, '{}'::int[], null, 'Seaside hawker centre famous for nasi lemak and satay bee hoon; planes glide overhead on approach to Changi.', '{}'::text[], 'No MRT nearby. Budget a taxi both ways.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/Changi_Village_10%2C_Jul_06.JPG/960px-Changi_Village_10%2C_Jul_06.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Changi Village'),
  ('changi-point-boardwalk', 'Changi Point Coastal Boardwalk', 'Changi', 1.3897, 103.9893, array['nature', 'views', 'photo', 'beach']::text[], 45, 0, false, 'Changi Airport', '"24h"'::jsonb, '{}'::int[], null, 'Timber boardwalk hugging the cliffs and mangroves of Changi Point, with views across to Pulau Ubin and Malaysia.', '{}'::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/Changi_Point_Coastal_Walk_%283185757671%29.jpg/960px-Changi_Point_Coastal_Walk_%283185757671%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Wikimedia Commons: edwin.11'),
  ('changi-beach-park', 'Changi Beach Park', 'Changi', 1.3913, 103.9918, array['beach', 'nature', 'photo']::text[], 40, 0, false, 'Changi Airport', '"24h"'::jsonb, '{}'::int[], null, 'Long, quiet beach at the island''s eastern tip. Best at sunset when the jets line up overhead.', '{}'::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/Changi_Beach_Park_5%2C_Jul_06.JPG/960px-Changi_Beach_Park_5%2C_Jul_06.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Changi Beach Park'),
  ('east-coast-lagoon', 'East Coast Lagoon Food Village', 'East Coast', 1.3066, 103.9342, array['hawker', 'food', 'beach']::text[], 50, 1, false, 'Tanah Merah', '[["10:30","22:30"]]'::jsonb, '{}'::int[], null, 'Open-air hawker centre on the beach: BBQ stingray, satay and sugarcane juice with sea breeze.', '{}'::text[], 'Open-air seating; move to the covered stalls if it rains.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/%28SGP-Singapore%29_East_Coast_Park_Zone_B_2026-01-25.jpg/960px-%28SGP-Singapore%29_East_Coast_Park_Zone_B_2026-01-25.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: East Coast Park'),
  ('east-coast-park', 'East Coast Park (Marine Cove)', 'East Coast', 1.3002, 103.913, array['beach', 'nature', 'photo']::text[], 45, 0, false, 'Marine Parade', '"24h"'::jsonb, '{}'::int[], null, '15 km of coastal park; rent a bike or just walk the promenade and watch container ships queue offshore.', '{}'::text[], null, null, null),
  ('koon-seng-shophouses', 'Koon Seng Road Peranakan Houses', 'East Coast', 1.3143, 103.9021, array['photo', 'heritage', 'architecture']::text[], 20, 0, false, 'Eunos', '"24h"'::jsonb, '{}'::int[], null, 'Row of candy-coloured Peranakan terrace houses with ornate tiles, Singapore''s most photographed doorways.', '{}'::text[], 'Residents live here. Keep voices down and stay off the five-foot ways.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/Colorful_shophouses_in_Koon_Seng_Road%2C_Singapore.jpg/960px-Colorful_shophouses_in_Koon_Seng_Road%2C_Singapore.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Wikimedia Commons: Basile Morin'),
  ('katong-laksa', '328 Katong Laksa', 'East Coast', 1.3052, 103.9048, array['food', 'hawker']::text[], 30, 1, true, 'Marine Parade', '[["09:30","21:30"]]'::jsonb, '{}'::int[], null, 'Coconut-rich laksa with cut noodles you eat with just a spoon. A Katong institution.', '{}'::text[], null, null, null),
  ('kim-choo', 'Kim Choo Kueh Chang', 'East Coast', 1.3057, 103.9039, array['food', 'heritage', 'shopping']::text[], 25, 1, true, 'Marine Parade', '[["09:00","21:00"]]'::jsonb, '{}'::int[], null, 'Family Peranakan shop for nyonya rice dumplings, kueh and beaded slippers.', '{}'::text[], null, null, null),
  ('geylang-serai-market', 'Geylang Serai Market', 'East Coast', 1.317, 103.8983, array['hawker', 'food', 'culture']::text[], 45, 1, true, 'Eunos', '[["07:00","22:00"]]'::jsonb, '{}'::int[], null, 'Heart of the Malay community: nasi padang, putu piring and a wet market downstairs.', '{}'::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Joo_Chiat_Road%2C_Apr_06.JPG/960px-Joo_Chiat_Road%2C_Apr_06.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Joo Chiat Road'),
  ('old-airport-road', 'Old Airport Road Food Centre', 'East Coast', 1.3081, 103.8858, array['hawker', 'food']::text[], 45, 1, true, 'Dakota', '[["07:00","22:00"]]'::jsonb, '{}'::int[], null, 'Built on Singapore''s first airport runway; 150 stalls, many of them local legends for char kway teow and lor mee.', '{}'::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/51_Old_Airport_Road_Food_Centre%2C_exterior.jpg/960px-51_Old_Airport_Road_Food_Centre%2C_exterior.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Wikimedia Commons: Kbseah'),
  ('supertree-grove', 'Supertree Grove', 'Marina Bay', 1.2816, 103.8636, array['gardens', 'photo', 'views', 'nature']::text[], 45, 0, false, 'Bayfront', '[["05:00","23:59"]]'::jsonb, '{}'::int[], null, 'Eighteen vertical gardens up to 50 m tall, the postcard of modern Singapore. Free to walk beneath.', array['Lie on the ground at 7:45 pm for Garden Rhapsody, the trees sing.', 'OCBC Skyway is a narrow 22 m-high walkway; closes in lightning.', 'Best photo: from the Dragonfly Bridge looking back at MBS.']::text[], 'Fully exposed: skip in thunderstorms, bring water at midday.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Supertree_Grove%2C_Gardens_by_the_Bay%2C_Singapore_-_20120712-02.jpg/960px-Supertree_Grove%2C_Gardens_by_the_Bay%2C_Singapore_-_20120712-02.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Gardens by the Bay'),
  ('cloud-forest', 'Cloud Forest', 'Marina Bay', 1.284, 103.8659, array['gardens', 'nature', 'photo']::text[], 60, 3, true, 'Gardens by the Bay', '[["09:00","21:00"]]'::jsonb, '{}'::int[], null, 'A cool, misty dome with a 35 m indoor mountain and a waterfall; walk the aerial path through the cloud.', array['Instant relief from the humidity, it''s 23°C inside.', 'Take the lift to the top and walk down the Cloud Walk.', 'Waterfall mist is strongest right when you walk in.']::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Supertree_Grove%2C_Gardens_by_the_Bay%2C_Singapore_-_20120712-02.jpg/960px-Supertree_Grove%2C_Gardens_by_the_Bay%2C_Singapore_-_20120712-02.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Gardens by the Bay'),
  ('flower-dome', 'Flower Dome', 'Marina Bay', 1.2842, 103.8642, array['gardens', 'photo']::text[], 45, 3, true, 'Bayfront', '[["09:00","21:00"]]'::jsonb, '{}'::int[], null, 'The world''s largest glass greenhouse, with Mediterranean gardens and a rotating seasonal flower show.', '{}'::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Supertree_Grove%2C_Gardens_by_the_Bay%2C_Singapore_-_20120712-02.jpg/960px-Supertree_Grove%2C_Gardens_by_the_Bay%2C_Singapore_-_20120712-02.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Gardens by the Bay'),
  ('garden-rhapsody', 'Garden Rhapsody light show', 'Marina Bay', 1.2819, 103.8641, array['gardens', 'photo', 'nightlife', 'views']::text[], 20, 0, false, 'Bayfront', '[["19:40","21:00"]]'::jsonb, '{}'::int[], null, 'Nightly sound-and-light show in the Supertree Grove at 7:45 and 8:45 pm. Free.', '{}'::text[], 'Cancelled in heavy rain or lightning.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Supertree_Grove%2C_Gardens_by_the_Bay%2C_Singapore_-_20120712-02.jpg/960px-Supertree_Grove%2C_Gardens_by_the_Bay%2C_Singapore_-_20120712-02.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Gardens by the Bay'),
  ('satay-by-the-bay', 'Satay by the Bay', 'Marina Bay', 1.2826, 103.8692, array['hawker', 'food']::text[], 45, 1, true, 'Gardens by the Bay', '[["11:00","23:00"]]'::jsonb, '{}'::int[], null, 'Covered hawker centre at the edge of Gardens by the Bay; smoky satay sticks with the Supertrees in view.', '{}'::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Supertree_Grove%2C_Gardens_by_the_Bay%2C_Singapore_-_20120712-02.jpg/960px-Supertree_Grove%2C_Gardens_by_the_Bay%2C_Singapore_-_20120712-02.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Gardens by the Bay'),
  ('mbs-skypark', 'Marina Bay Sands SkyPark', 'Marina Bay', 1.283, 103.8607, array['views', 'photo']::text[], 45, 3, false, 'Bayfront', '[["10:00","22:00"]]'::jsonb, '{}'::int[], null, 'Observation deck 57 floors up on the ship-shaped roof; 360° views of the bay, the Gardens and the straits.', '{}'::text[], 'Outdoor deck. Closes in lightning.', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/Marina_Bay_Sands_%28I%29.jpg/960px-Marina_Bay_Sands_%28I%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Marina Bay Sands'),
  ('spectra-show', 'Spectra light & water show', 'Marina Bay', 1.2837, 103.8594, array['photo', 'nightlife', 'views']::text[], 20, 0, false, 'Bayfront', '[["19:50","21:15"]]'::jsonb, '{}'::int[], null, 'Free fountain, laser and projection show on the MBS Event Plaza at 8 and 9 pm.', '{}'::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/Marina_Bay_Sands_%28I%29.jpg/960px-Marina_Bay_Sands_%28I%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Marina Bay Sands'),
  ('shoppes-mbs', 'The Shoppes at Marina Bay Sands', 'Marina Bay', 1.284, 103.8591, array['shopping', 'architecture']::text[], 40, 2, true, 'Bayfront', '[["10:00","23:00"]]'::jsonb, '{}'::int[], null, 'Air-conditioned mall with an indoor canal and the Rain Oculus, a vortex of water falling into a sampan pool.', '{}'::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/Marina_Bay_Sands_%28I%29.jpg/960px-Marina_Bay_Sands_%28I%29.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Marina Bay Sands'),
  ('artscience-museum', 'ArtScience Museum', 'Marina Bay', 1.2863, 103.8593, array['museum', 'art']::text[], 75, 2, true, 'Bayfront', '[["10:00","19:00"]]'::jsonb, '{}'::int[], null, 'Lotus-shaped museum with immersive digital art (Future World) and big touring exhibitions.', array['Future World is a hit with anyone who likes glowing rooms.', 'The lotus roof collects rainwater into a centre waterfall.', 'Book a timed slot on weekends.']::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/ArtScience_Museum%2C_Marina_Bay_Sands%2C_Singapore.jpg/960px-ArtScience_Museum%2C_Marina_Bay_Sands%2C_Singapore.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: ArtScience Museum'),
  ('helix-bridge', 'Helix Bridge', 'Marina Bay', 1.2876, 103.8604, array['photo', 'architecture', 'views']::text[], 15, 0, false, 'Promenade', '"24h"'::jsonb, '{}'::int[], null, 'DNA-inspired steel footbridge that frames the MBS towers; lit up after dark.', '{}'::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/Double-Helix-Bridge.jpg/960px-Double-Helix-Bridge.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Helix Bridge'),
  ('merlion-park', 'Merlion Park', 'Marina Bay', 1.2868, 103.8545, array['photo', 'views']::text[], 25, 0, false, 'Raffles Place', '"24h"'::jsonb, '{}'::int[], null, 'The half-lion, half-fish mascot spouting into the bay, with MBS as the backdrop. Required selfie.', array['Everyone does the ''drinking the fountain'' photo. Everyone.', 'Come before 9 am to beat the tour buses.', 'The mini Merlion cub is behind the big one.']::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2e/Singapore_Skyline_2019-10.jpg/960px-Singapore_Skyline_2019-10.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Merlion'),
  ('esplanade', 'Esplanade – Theatres on the Bay', 'Marina Bay', 1.2897, 103.8558, array['architecture', 'art', 'views']::text[], 30, 0, true, 'Esplanade', '[["09:00","23:00"]]'::jsonb, '{}'::int[], null, 'The ''durian'' domes; free outdoor gigs on the waterfront and a quiet rooftop terrace with bay views.', '{}'::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/The_Esplanade_%E2%80%93_Theatres_on_the_Bay.jpg/960px-The_Esplanade_%E2%80%93_Theatres_on_the_Bay.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Esplanade – Theatres on the Bay'),
  ('gluttons-bay', 'Makansutra Gluttons Bay', 'Marina Bay', 1.2893, 103.8563, array['hawker', 'food', 'nightlife']::text[], 45, 1, false, 'Esplanade', '[["17:00","23:59"]]'::jsonb, '{}'::int[], null, 'Evening-only hawker row on the water: carrot cake, BBQ seafood and satay under the city lights.', '{}'::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/Wikimania_2023-Food-Makansutra_Gluttons_Bay-204156.jpg/960px-Wikimania_2023-Food-Makansutra_Gluttons_Bay-204156.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail', 'Wikimedia Commons: Rainer Halama'),
  ('lau-pa-sat', 'Lau Pa Sat', 'Marina Bay', 1.2806, 103.8504, array['hawker', 'food', 'heritage', 'architecture']::text[], 45, 1, true, 'Raffles Place', '"24h"'::jsonb, '{}'::int[], null, 'Victorian cast-iron market hall in the CBD; after 7 pm Boon Tat Street closes for satay grills.', array['Satay Street starts around 7 pm, follow the smoke.', 'The octagonal iron roof was shipped from Glasgow in 1894.', 'Open 24 hours, useful for a very early or very late layover.']::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Lau_Pa_Sat_Singapore_2.jpg/960px-Lau_Pa_Sat_Singapore_2.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Lau Pa Sat'),
  ('marina-barrage', 'Marina Barrage', 'Marina Bay', 1.2807, 103.8713, array['views', 'nature', 'photo']::text[], 40, 0, false, 'Gardens by the Bay', '"24h"'::jsonb, '{}'::int[], null, 'Dam with a grassy green roof where locals fly kites; skyline views across the reservoir.', '{}'::text[], null, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Marina_Barrage_Closeup_300522.jpg/960px-Marina_Barrage_Closeup_300522.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail', 'Wikipedia: Marina Barrage'),
